'use strict';
const $ = s=>document.querySelector(s);
const esc = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v=>{const n=BigInt(v||'0');return `${n/1000000n}.${(n%1000000n).toString().padStart(6,'0').replace(/0+$/,'').padEnd(3,'0')}`;};
let state=null,loading=false,balanceLoading=false,seenPaid=null,lastOrders='';
async function get(path){const r=await fetch(path,{signal:AbortSignal.timeout(45000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Local vendor unavailable');return d;}
function error(message){$('#error').textContent=message;$('#error').hidden=!message;}
function theme(value){document.documentElement.dataset.theme=value;$('#theme').textContent=value==='dark'?'Light theme':'Dark theme';try{localStorage.setItem('vendor.theme',value);}catch{}}
try{theme(localStorage.getItem('vendor.theme')||'light');}catch{theme('light');}
$('#theme').onclick=()=>theme(document.documentElement.dataset.theme==='dark'?'light':'dark');
async function balance(){if(balanceLoading)return;balanceLoading=true;$('#refresh').disabled=true;try{const d=await get('/api/balance');$('#balance').textContent=money(d.usdc_atomic);$('#balance-note').textContent=`Verified ${new Date(d.checked_at).toLocaleTimeString()} · ${d.sol} SOL`;$('#setup').hidden=d.usdc_token_accounts>0;}catch{ $('#balance-note').textContent='Balance could not be refreshed. Any displayed balance is from the previous check.';}finally{balanceLoading=false;$('#refresh').disabled=false;}}
$('#refresh').onclick=balance;
$('#copy').onclick=async()=>{if(!state)return;try{await navigator.clipboard.writeText(state.address);$('#copy').textContent='Copied';setTimeout(()=>$('#copy').textContent='Copy address',1800);}catch{error('Select the receiving address above to copy it.');}};
function order(row){const settled=row.status==='SETTLED';return `<article class="order"><div><span class="status ${settled?'settled':''}">${esc(row.status)}</span><p class="id">${esc(row.id.slice(0,16))}…</p><p class="muted">${esc(new Date(row.created_at).toLocaleString())}</p>${row.payer?`<p class="id">FROM ${esc(row.payer)}</p>`:''}${settled?`<a class="receipt" target="_blank" rel="noopener noreferrer" href="https://explorer.solana.com/tx/${encodeURIComponent(row.proof.signature)}?cluster=devnet">Confirmed transaction ↗ ${esc(row.proof.signature.slice(0,20))}…</a>`:['SETTLING','PENDING'].includes(row.status)?`<button data-recheck="${esc(row.id)}">Recheck receipt</button>`:'<p class="muted">Free quote issued · no payment received</p>'}</div><div class="amount">${money(row.amount)}<p class="muted">USDC ${settled?'RECEIVED':'QUOTED'}</p></div></article>`;}
async function refresh(){if(loading)return;loading=true;try{state=await get('/api/state');$('#address').textContent=state.address;$('#explorer').href=`https://explorer.solana.com/address/${encodeURIComponent(state.address)}?cluster=devnet`;$('#revenue').textContent=money(state.revenue_atomic);$('#paid-count').textContent=state.settled_orders;const key=JSON.stringify(state.orders);if(key!==lastOrders){$('#orders').innerHTML=state.orders.length?state.orders.map(order).join(''):'<p class="empty">No orders yet. Buy the demo vendor service from Governor.</p>';lastOrders=key;}$('#live').textContent='● LIVE / UPDATES EVERY 1.5s';error('');if(seenPaid!==state.settled_orders){seenPaid=state.settled_orders;balance();}}catch(e){error(e.message);$('#live').textContent='CONNECTION LOST';}finally{loading=false;}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-recheck]');if(!b)return;b.disabled=true;try{await get('/api/orders/'+encodeURIComponent(b.dataset.recheck));await refresh();}catch(e){error(e.message);}finally{if(b.isConnected)b.disabled=false;}});
refresh();setInterval(()=>{if(!document.hidden)refresh();},1500);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
